import { APPEAR_DURATION, PROJECT_LIST_OFFSET_EMPTY } from '@/constants'
import { colors, Theme, useTheme } from '@/theme'
import { MotiView } from 'moti'
import {
	RefreshControl,
	ScrollView,
	StyleSheet,
	Text,
	Platform
} from 'react-native'
import { Image } from 'expo-image'
import { defineStyles } from '@/utils/defineStyles'
import { useBottomTabBarHeight } from '@/utils/hooks/useBottomTabBarHeight'

const canDoLiquidGlass =
	Platform.OS === 'ios' && Number.parseFloat(Platform.Version) >= 26.0

type EmptyStateContainerProps = {
	isShining: boolean
	isEmpty: boolean
	isRefreshing: boolean
	onRefresh: () => void
	text: string
}

export const EmptyStateContainer = ({
	isShining,
	isEmpty,
	isRefreshing,
	onRefresh,
	text
}: EmptyStateContainerProps) => {
	const tabBarHeight = useBottomTabBarHeight()
	const { theme, isDark } = useTheme()

	return (
		<ScrollView
			showsVerticalScrollIndicator={false}
			refreshControl={
				<RefreshControl
					refreshing={isRefreshing}
					onRefresh={onRefresh}
					progressViewOffset={PROJECT_LIST_OFFSET_EMPTY}
				/>
			}
			style={StyleSheet.absoluteFill}
			contentContainerStyle={styles.scrollViewContainer}
		>
			<MotiView
				from={{ opacity: 0.3 }}
				animate={{
					opacity: isShining ? 0.3 : isEmpty ? 1 : 0
				}}
				transition={{
					type: 'timing',
					duration: APPEAR_DURATION
				}}
				style={[
					styles.splashIconContainer,
					!canDoLiquidGlass && { top: tabBarHeight }
				]}
			>
				<Image
					source={{ uri: 'splash-icon' }}
					style={styles.splashIcon(theme, isDark)}
				/>
			</MotiView>
			<MotiView
				from={{ opacity: 0 }}
				animate={{
					opacity: !isShining && isEmpty ? 1 : 0,
					transform: [
						{
							translateY: !isShining && isEmpty ? 80 : 140
						}
					]
				}}
				transition={{
					type: 'timing',
					duration: APPEAR_DURATION
				}}
				style={[
					styles.emptyStateTextContainer,
					!canDoLiquidGlass && { top: tabBarHeight }
				]}
			>
				<Text style={styles.emptyStateText(theme)}>{text}</Text>
			</MotiView>
		</ScrollView>
	)
}

const styles = defineStyles({
	scrollViewContainer: {
		flex: 1,
		alignItems: 'center'
	},
	splashIconContainer: {
		alignItems: 'center',
		justifyContent: 'center',
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		zIndex: 1
	},
	splashIcon: (theme: Theme, isDark: boolean) => ({
		width: 72,
		height: 75,
		tintColor: isDark ? colors[theme].gray[500] : undefined
	}),
	emptyStateTextContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center'
	},
	emptyStateText: (theme: Theme) => ({
		color: colors[theme].gray[200],
		fontSize: 18,
		fontWeight: '500',
		width: 200,
		textAlign: 'center',
		lineHeight: 24
	})
})
